function lookupKeyCode(code){
  code=Math.floor(Number(code));
  if(isNaN(code)||code<0||code>255) throw new Error('keyCode 范围 0-255');
  return { keyCode:code, name:KEYCODE_TABLE[code]||'(未知/厂商相关)', known:!!KEYCODE_TABLE[code] };
}
function describeKey(ev){
  var mods=[];
  if(ev.ctrlKey) mods.push('Ctrl');
  if(ev.shiftKey) mods.push('Shift');
  if(ev.altKey) mods.push('Alt');
  if(ev.metaKey) mods.push('Meta');
  return {
    key: ev.key===' ' ? 'Space' : String(ev.key),
    code: String(ev.code||''),
    keyCode: Number(ev.keyCode||ev.which||0),
    modifiers: mods,
    combo: mods.concat([ev.key===' '?'Space':String(ev.key)]).join(' + ')
  };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { lookupKeyCode:lookupKeyCode, describeKey:describeKey, KEYCODE_TABLE:KEYCODE_TABLE };
}
if (typeof window !== 'undefined') {
  window.KeyForgePure = { lookupKeyCode:lookupKeyCode, describeKey:describeKey, KEYCODE_TABLE:KEYCODE_TABLE };
}
